//! Realtime values from go-foks main (fixtures in `foks-main/realtime`,
//! generated by `tools/foks-main-oracle`), decoded alongside v0.1.9.
use foks_proto::*;
use foks_rpc::*;
use foks_snowpack::Value;
use std::io::Cursor;

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "../foks-snowpack/tests/fixtures/foks-main/realtime/{name}"
    ))
    .unwrap()
}
fn v019(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "../foks-snowpack/tests/fixtures/foks-v0.1.9/realtime/{name}"
    ))
    .unwrap()
}
fn send_request() -> RealtimeRequest {
    let wire = v019("request-3.frame");
    let call = read_call(&mut Cursor::new(&wire), DEFAULT_MAX_FRAME_LENGTH).unwrap();
    RealtimeRequest::decode_argument(3, call.argument()).unwrap()
}
fn with_fields(bytes: &[u8], extra: &[Value]) -> Vec<u8> {
    let Value::Array(mut fields) = foks_snowpack::decode(bytes).unwrap() else {
        panic!("positional struct")
    };
    fields.extend_from_slice(extra);
    foks_snowpack::encode(&Value::Array(fields)).unwrap()
}

#[test]
fn send_results_with_was_replay_decode_and_reencode_exactly() {
    let request = send_request();
    for (name, replay) in [("fresh", false), ("replay", true)] {
        let bytes = fixture(&format!("send-res-{name}.snowp"));
        let receipt = ChatSendReceipt::decode(&bytes).unwrap();
        assert_eq!(receipt.sequence, 1);
        assert_eq!(receipt.insert_time, 1_700_000_000_001);
        assert_eq!(receipt.was_replay, replay);
        assert_eq!(receipt.encoded().unwrap(), bytes);
        let frame = fixture(&format!("response-3-{name}.frame"));
        let data = read_response(&mut Cursor::new(&frame), DEFAULT_MAX_FRAME_LENGTH, 7).unwrap();
        assert_eq!(data, bytes);
        assert_eq!(
            request.decode_result(&data).unwrap(),
            RealtimeResponse::Sent(receipt)
        );
    }
    // A v0.1.9 server omits the field, which decodes as false and re-encodes
    // in the same two-field form.
    let frame = v019("response-3.frame");
    let data = read_response(&mut Cursor::new(&frame), DEFAULT_MAX_FRAME_LENGTH, 7).unwrap();
    let RealtimeResponse::Sent(old) = request.decode_result(&data).unwrap() else {
        panic!("send result")
    };
    assert!(!old.was_replay);
    assert_eq!(old.encoded().unwrap(), data);
    // Only the flag differs between the v0.1.9 and main encodings.
    let fresh = ChatSendReceipt::decode(&fixture("send-res-fresh.snowp")).unwrap();
    assert_eq!(fresh, old);
    let constructed = ChatSendReceipt {
        sequence: 1,
        insert_time: 1_700_000_000_001,
        was_replay: false,
        trailing: TrailingFields::default(),
    };
    assert_eq!(constructed.encoded().unwrap(), data);
    let replayed = ChatSendReceipt {
        was_replay: true,
        ..constructed
    };
    assert_eq!(
        replayed.encoded().unwrap(),
        fixture("send-res-replay.snowp")
    );
}

#[test]
fn send_results_retain_unknown_trailing_fields() {
    let bytes = with_fields(
        &fixture("send-res-fresh.snowp"),
        &[Value::Unsigned(5), Value::Text(b"x".to_vec())],
    );
    let receipt = ChatSendReceipt::decode(&bytes).unwrap();
    assert!(!receipt.was_replay);
    assert_eq!(receipt.trailing.unknown().len(), 2);
    assert_eq!(receipt.encoded().unwrap(), bytes);
    assert!(ChatSendReceipt::decode(&[0x91, 0x01]).is_err());
    assert!(ChatSendReceipt::decode(&with_fields(&fixture("send-res-fresh.snowp"), &[])).is_ok());
    // A wrongly typed known optional field is still rejected.
    let wrong = foks_snowpack::encode(&Value::Array(vec![
        Value::Unsigned(1),
        Value::Unsigned(2),
        Value::Unsigned(3),
    ]))
    .unwrap();
    assert!(ChatSendReceipt::decode(&wrong).is_err());
}

#[test]
fn channel_metadata_with_no_push_round_trips() {
    let old = RtChannelMetadata::decode(&v019("channel.snowp")).unwrap();
    assert!(!old.no_push);
    assert_eq!(old.encoded().unwrap(), v019("channel.snowp"));
    for (name, no_push) in [("channel-no-push", true), ("channel-push", false)] {
        let bytes = fixture(&format!("{name}.snowp"));
        let md = RtChannelMetadata::decode(&bytes).unwrap();
        assert_eq!(md.no_push, no_push);
        assert!(md.trailing.unknown().is_empty());
        assert_eq!(md.encoded().unwrap(), bytes);
        assert_eq!(md.id, old.id);
        assert_eq!(md.name, old.name);
    }
    // Setting the flag on a locally built value emits the fourteenth field;
    // clearing it returns to the thirteen-field form.
    let mut local = RtChannelMetadata::decode(&fixture("channel-no-push.snowp")).unwrap();
    local.trailing = TrailingFields::default();
    assert_eq!(local.encoded().unwrap(), fixture("channel-no-push.snowp"));
    local.no_push = false;
    let Value::Array(fields) = foks_snowpack::decode(&local.encoded().unwrap()).unwrap() else {
        panic!("positional struct")
    };
    assert_eq!(fields.len(), 13);
}

#[test]
fn channel_metadata_retains_unknown_fields_in_containers() {
    let extra = [Value::Unsigned(77), Value::Binary(vec![1, 2, 3])];
    let bytes = with_fields(&fixture("channel-no-push.snowp"), &extra);
    let md = RtChannelMetadata::decode(&bytes).unwrap();
    assert!(md.no_push);
    assert_eq!(md.trailing.unknown(), &extra);
    assert_eq!(md.encoded().unwrap(), bytes);
    let inbox = RtInboxChannel {
        metadata: md.clone(),
        inbox_version: 4,
        read_through: 1,
        hidden: false,
        muted: true,
    };
    assert_eq!(
        RtInboxChannel::decode(&inbox.encoded().unwrap()).unwrap(),
        inbox
    );
    let set = RtChannelSet {
        version: 1,
        channels: vec![md.clone()],
        mtime: 2,
    };
    let decoded = RtChannelSet::decode(&set.encoded().unwrap()).unwrap();
    assert_eq!(decoded.channels[0].trailing.unknown(), &extra);
    assert_eq!(decoded.encoded().unwrap(), set.encoded().unwrap());
    // Too few fields are still rejected.
    let Value::Array(mut fields) = foks_snowpack::decode(&v019("channel.snowp")).unwrap() else {
        panic!("positional struct")
    };
    fields.pop();
    assert!(RtChannelMetadata::from_value(&Value::Array(fields)).is_err());
}

#[test]
fn go_main_channel_creation_and_listing_frames_decode() {
    let wire = fixture("request-0-no-push.frame");
    let call = read_call(&mut Cursor::new(&wire), DEFAULT_MAX_FRAME_LENGTH).unwrap();
    assert_eq!(call.protocol_id(), REAL_TIME_PROTOCOL_ID);
    let request = RealtimeRequest::decode_argument(0, call.argument()).unwrap();
    let RealtimeRequest::CreateChannel(arg) = &request else {
        panic!("rtNewChannel")
    };
    assert!(arg.metadata.no_push);
    assert_eq!(arg.set_version, 1);
    assert_eq!(request.encode_at(7).unwrap(), wire);

    let list = RealtimeRequest::ListChannels(RtListChannelsArgument {
        team: arg.metadata.team.clone(),
        app: RtAppId::Chat,
        last: 0,
    });
    let frame = fixture("response-2-no-push.frame");
    let data = read_response(&mut Cursor::new(&frame), DEFAULT_MAX_FRAME_LENGTH, 7).unwrap();
    let RealtimeResponse::Channels(set) = list.decode_result(&data).unwrap() else {
        panic!("channel set")
    };
    assert!(set.channels[0].no_push);
    assert_eq!(set.encoded().unwrap(), data);
}

#[test]
fn replay_mismatch_status_matches_go_main_and_carries_no_payload() {
    let wire = encode_status_response_at(&RpcStatus::RtMessageReplayMismatch, 7).unwrap();
    assert_eq!(wire, fixture("status-12007.frame"));
    assert!(matches!(
        read_response(&mut Cursor::new(wire), DEFAULT_MAX_FRAME_LENGTH, 7),
        Err(foks_rpc::Error::RemoteStatus { code: 12007, .. })
    ));
}

#[test]
fn hashed_and_signed_realtime_structs_still_decode_exactly() {
    let noncer = v019("noncer.snowp");
    assert!(RtMessageNoncer::decode(&noncer).is_ok());
    assert!(RtMessageNoncer::decode(&with_fields(&noncer, &[Value::Bool(false)])).is_err());
    let message = v019("message.snowp");
    assert!(RtMessage::decode(&message).is_ok());
    assert!(RtMessage::decode(&with_fields(&message, &[Value::Bool(false)])).is_err());
    let RealtimeRequest::Send(arg) = send_request() else {
        panic!("send")
    };
    let bytes = arg.send.encoded().unwrap();
    assert!(RtSend::decode(&with_fields(&bytes, &[Value::Unsigned(0)])).is_err());
}
